const express = require('express');
const https = require('https');
const http = require('http');
const { URL } = require('url');
const crypto = require('crypto');

const app = express();
app.use(express.json());

// Configuration
const ALLOWED_WEBHOOK_HOSTS = new Set([
  'hooks.slack.com',
  'discord.com',
  'api.github.com',
  'webhook.site'
]);

const INTERNAL_RANGES = [
  /^127\./,
  /^10\./,
  /^172\.(1[6-9]|2[0-9]|3[01])\./,
  /^192\.168\./,
  /^169\.254\./,
  /^0\./
];

// Token store for authenticated webhooks
const tokenStore = new Map();
// Webhook URL store - URLs are stored at registration, not re-supplied
const webhookStore = new Map();

function generateToken(userId) {
  const token = crypto.randomBytes(32).toString('hex');
  tokenStore.set(userId, token);
  return token;
}

// Normalize hostname for security comparison
// Handles internationalized domain names
function normalizeHostname(hostname) {
  // Remove trailing dot (FQDN notation)
  let normalized = hostname.replace(/\.$/, '');
  // Convert to lowercase for comparison
  normalized = normalized.toLowerCase();
  // Handle punycode - decode to unicode for display/comparison
  try {
    // Use URL constructor to normalize punycode
    const testUrl = new URL(`http://${normalized}`);
    normalized = testUrl.hostname;
  } catch (e) {
    // If URL parsing fails, use as-is
  }
  return normalized;
}

// Validate that a URL is safe to request
function isAllowedWebhookTarget(urlString) {
  try {
    const parsed = new URL(urlString);

    // Must be HTTPS
    if (parsed.protocol !== 'https:') {
      return { allowed: false, reason: 'Must use HTTPS' };
    }

    // Check for IP literals
    const hostname = parsed.hostname;
    // Strip brackets from IPv6
    const bareHost = hostname.replace(/^\[|\]$/g, '');

    // Block IP literals entirely
    if (/^[\d.]+$/.test(bareHost) || bareHost.includes(':')) {
      return { allowed: false, reason: 'IP literals not allowed' };
    }

    // Normalize and check against allowlist
    const normalizedHost = normalizeHostname(hostname);

    // Must exactly match an allowed host (no subdomain matching)
    if (!ALLOWED_WEBHOOK_HOSTS.has(normalizedHost)) {
      return { allowed: false, reason: `Host '${normalizedHost}' not in allowlist` };
    }

    return { allowed: true };
  } catch (e) {
    return { allowed: false, reason: 'Invalid URL' };
  }
}

// Build the webhook URL from user-provided components
function buildWebhookUrl(host, path, queryParams) {
  // Ensure host and path are strings before performing string/regex operations
  if (typeof host !== 'string' || typeof path !== 'string') {
    throw new Error('host and path must be strings');
  }

  // Validate host doesn't contain path separators or special chars
  if (/[\/@#?\\]/.test(host)) {
    throw new Error('Invalid host characters');
  }

  // Ensure path starts with / and doesn't contain host-changing sequences
  const safePath = path.startsWith('/') ? path : `/${path}`;
  if (safePath.includes('//') || safePath.includes('\\') || safePath.includes('@')) {
    throw new Error('Invalid path characters');
  }

  // Build query string
  let queryString = '';
  if (queryParams && typeof queryParams === 'object' && !Array.isArray(queryParams)) {
    const params = new URLSearchParams();
    for (const [key, value] of Object.entries(queryParams)) {
      // Only allow alphanumeric keys
      if (/^[a-zA-Z0-9_]+$/.test(key)) {
        params.append(key, String(value));
      }
    }
    queryString = params.toString();
  }

  const url = `https://${host}${safePath}${queryString ? '?' + queryString : ''}`;
  return url;
}

// Send webhook notification
async function sendWebhook(webhookUrl, payload, authToken) {
  return new Promise((resolve, reject) => {
    const parsed = new URL(webhookUrl);

    const postData = JSON.stringify(payload);

    const options = {
      hostname: parsed.hostname,
      port: parsed.port || 443,
      path: parsed.pathname + parsed.search,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData),
        'User-Agent': 'WebhookService/1.0',
        ...(authToken ? { 'Authorization': `Bearer ${authToken}` } : {})
      },
      rejectUnauthorized: true,
      timeout: 5000
    };

    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => resolve({ status: res.statusCode, body: data }));
    });

    req.on('error', reject);
    req.on('timeout', () => { req.destroy(); reject(new Error('Timeout')); });
    req.write(postData);
    req.end();
  });
}

// Webhook registration endpoint
app.post('/api/webhooks/register', (req, res) => {
  const { userId, host, path, queryParams } = req.body;

  if (!userId || !host || !path) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  // Validate input types to prevent type confusion / unexpected Map key usage
  if (typeof userId !== 'string' || typeof host !== 'string' || typeof path !== 'string') {
    return res.status(400).json({ error: 'userId, host, and path must be strings' });
  }

  try {
    // Build the full webhook URL
    const webhookUrl = buildWebhookUrl(host, path, queryParams);

    // Validate the webhook target
    const validation = isAllowedWebhookTarget(webhookUrl);
    if (!validation.allowed) {
      return res.status(403).json({ error: validation.reason });
    }

    // Generate auth token and store the validated URL
    const token = generateToken(userId);
    webhookStore.set(userId, webhookUrl);

    res.json({
      webhookUrl,
      token,
      message: 'Webhook registered successfully'
    });
  } catch (err) {
    return res.status(400).json({ error: err.message });
  }
});

// Webhook trigger endpoint
app.post('/api/webhooks/trigger', async (req, res) => {
  const { userId, event, data } = req.body;

  if (!userId || typeof userId !== 'string' || !tokenStore.has(userId)) {
    return res.status(401).json({ error: 'Not registered' });
  }

  // Use the stored, pre-validated webhook URL
  const webhookUrl = webhookStore.get(userId);
  if (!webhookUrl) {
    return res.status(404).json({ error: 'No webhook configured' });
  }

  // Re-validate on every trigger for defense in depth
  const validation = isAllowedWebhookTarget(webhookUrl);
  if (!validation.allowed) {
    return res.status(403).json({ error: validation.reason });
  }

  const token = tokenStore.get(userId);

  try {
    const result = await sendWebhook(webhookUrl, { event, data, timestamp: Date.now() }, token);
    res.json({ success: true, status: result.status });
  } catch (err) {
    res.status(502).json({ error: 'Webhook delivery failed', detail: err.message });
  }
});

app.listen(3000, () => console.log('Webhook service running on :3000'));

module.exports = app;
